// Garbage collection example
function createObjects() {
  // Local variable - will be garbage collected
  const localObject = { data: 'temporary' };

  // Returned object - stays reachable
  return { data: 'persistent' };
}

const persistent = createObjects();
// localObject is garbage collected
// persistent remains in memory

// Global reference - never garbage collected
const globalLeak = [];

function addToLeak() {
  globalLeak.push({ data: 'leaked' });
  // These objects never get garbage collected
}

// Bad: Event listener never removed
function setupLeakyListener() {
  const button = document.getElementById('myButton');
  button.addEventListener('click', handleClick);
  // If button is removed from DOM, listener keeps it in memory
}

// Good: Remove event listener
function setupCleanListener() {
  const button = document.getElementById('myButton');
  const handleClick = () => console.log('clicked');

  button.addEventListener('click', handleClick);

  // Cleanup function
  return () => {
    button.removeEventListener('click', handleClick);
  };
}

// React useEffect cleanup
function MyComponent() {
  useEffect(() => {
    const handleClick = () => console.log('clicked');
    window.addEventListener('resize', handleClick);

    return () => {
      window.removeEventListener('resize', handleClick);
    };
  }, []);
}

// Bad: Closure captures large object
function createClosure() {
  const largeData = new Array(1000000).fill('data');

  return function() {
    // This closure keeps largeData alive indefinitely
    console.log('Closure size:', largeData.length);
  };
}

const closure = createClosure();
// largeData never gets garbage collected

// Good: Minimize closure scope
function createOptimizedClosure() {
  const largeData = new Array(1000000).fill('data');
  const summary = largeData.length;

  return function() {
    // Only keep what's needed
    console.log('Closure size:', summary);
  };
  // largeData can be garbage collected
}

// Bad: Timer never cleared
function startLeakyTimer() {
  const data = { large: new Array(1000000).fill('data') };

  setInterval(() => {
    console.log('Processing:', data.large.length);
  }, 1000);
  // data never gets garbage collected
}

// Good: Clear timer when done
function startCleanTimer() {
  const data = { large: new Array(1000000).fill('data') };
  const intervalId = setInterval(() => {
    console.log('Processing:', data.large.length);
  }, 1000);

  // Cleanup function
  return () => {
    clearInterval(intervalId);
  };
}

// React cleanup pattern
function TimerComponent() {
  useEffect(() => {
    const intervalId = setInterval(() => {
      console.log('Timer tick');
    }, 1000);

    return () => clearInterval(intervalId);
