// Bad: DOM reference kept in variable
let removedElement;

function removeElement() {
  const element = document.getElementById('myElement');
  removedElement = element; // Keep reference
  element.remove(); // Element removed from DOM but not from memory
}

// Good: Clear references
function removeElementClean() {
  const element = document.getElementById('myElement');
  element.remove();
  // Let element be garbage collected
}

// React pattern: avoid direct DOM references
function Component() {
  const elementRef = useRef(null);

  useEffect(() => {
    return () => {
      // Clear ref when component unmounts
      elementRef.current = null;
    };
  }, []);
}

// Bad: Large state never cleaned up
function LargeStateComponent() {
  const [largeData, setLargeData] = useState(
    new Array(1000000).fill('data')
  );

  // State persists even if component is hidden/unmounted
  return <div>Data size: {largeData.length}</div>;
}

// Good: Clean up large state
function OptimizedComponent() {
  const [largeData, setLargeData] = useState(null);

  useEffect(() => {
    // Load data only when needed
    const data = new Array(1000000).fill('data');
    setLargeData(data);

    return () => {
      // Clean up when unmounting
      setLargeData(null);
    };
  }, []);

  if (!largeData) return <div>Loading...</div>;
  return <div>Data size: {largeData.length}</div>;
}

// Memory monitoring utility
function monitorMemory() {
  if (!performance.memory) {
    console.warn('Memory API not available');
    return;
  }

  const checkMemory = () => {
    const memory = performance.memory;
    const usedMB = (memory.usedJSHeapSize / 1048576).toFixed(2);
    const totalMB = (memory.totalJSHeapSize / 1048576).toFixed(2);
    const limitMB = (memory.jsHeapSizeLimit / 1048576).toFixed(2);

    console.log(`Memory: ${usedMB}MB / ${totalMB}MB (limit: ${limitMB}MB)`);

    // Alert if approaching limit
    if (memory.usedJSHeapSize > memory.jsHeapSizeLimit * 0.9) {
      console.warn('Memory usage approaching limit!');
    }
  };

  // Check every 5 seconds
  const intervalId = setInterval(checkMemory, 5000);

  return () => clearInterval(intervalId);
}

// Usage
